 q=dict(id=qid,paper_id=pid,locator=loc,printed_pages=pages,file_pages=pages,quote_markdown=quote,quote_scope=scope,transcription_status='Manually transcribed or rechecked and visually checked against the rendered original PDF page(s) in this task.',typography_note='Typeset line breaks and line-end hyphenation are joined. Ligatures use ordinary letters. Mathematical symbols use KaTeX. Editorial text stays outside the quotation.',symbol_transcription=symbols,evidence=[evidence(pid,p) for p in pages]);quotes.append(q)
